#!/usr/bin/env bash
# The outputs file: written after up, left alone by preview, checked and
# regenerated by the .outputs target, and never holding a secret's value.
source "$(dirname "$0")/testlib.sh"
setup

file="$BUILD_WORKSPACE_DIRECTORY/program/dev_outputs.bzl"

"$STACK" stack init dev
"$STACK" config set greeting hello
"$STACK" config set --secret token sekrit

"$STACK" preview --non-interactive >/dev/null
[[ ! -e "$file" ]] || fail "preview wrote the outputs file"

"$STACK" up --yes --skip-preview --non-interactive
[[ -f "$file" ]] || fail "up did not write $file"
grep -q '"greeting": "hello"' "$file" || fail "the outputs file lacks greeting: $(cat "$file")"
grep -q '"token": "\[secret\]"' "$file" || fail "the secret output is not a placeholder: $(cat "$file")"
if grep -q sekrit "$file"; then
    fail "the secret's value is in the outputs file"
fi
grep -q 'bazel run //program:dev.outputs' "$file" || fail "the header does not say how to regenerate"

# Same structure as the checked-in sample the BUILD file loads: only the JSON
# between the markers may differ.
strip_json() { sed "/^_RAW = json.decode(r'''\$/,/^''')\$/d" "$1"; }
diff <(strip_json "$file") <(strip_json "$FIXTURE") ||
    fail "the outputs file's structure differs from the loaded sample $FIXTURE"

"$OUTPUTS" --check || fail "--check failed on a fresh outputs file"

echo "# stale" >>"$file"
if "$OUTPUTS" --check 2>/dev/null; then
    fail "--check passed on a stale outputs file"
fi
"$OUTPUTS"
"$OUTPUTS" --check || fail "the .outputs target did not regenerate the file"

"$STACK" config set greeting changed
"$STACK" up --yes --skip-preview --non-interactive
grep -q '"greeting": "changed"' "$file" || fail "up did not rewrite the outputs file"

# Aliases count, help does not, and a destroy that removes the stack leaves
# an empty outputs file rather than a failure.
"$STACK" config set greeting via-update
"$STACK" update --yes --skip-preview --non-interactive
grep -q '"greeting": "via-update"' "$file" || fail "update did not write the outputs file"
rm "$file"
"$STACK" up --help >/dev/null || fail "up --help failed"
[[ ! -e "$file" ]] || fail "up --help wrote the outputs file"
"$STACK" destroy --yes --remove --non-interactive || fail "destroy --remove failed"
grep -q '^{}$' "$file" || fail "destroy --remove did not leave empty outputs: $(cat "$file")"

if "$OUTPUTS" extra-argument 2>/dev/null; then
    fail "the .outputs target accepted an unknown argument"
fi
echo PASS
